-- Link Prediction Tables
--
-- knowledge_predicted_links: Stores probabilistic link predictions generated by the
-- TransE-style translational embedding approach. Each record represents a candidate
-- relationship between two knowledge nodes with a confidence score. Predictions can
-- be approved (promoted to verified edges) or rejected by human reviewers.
--
-- knowledge_node_embeddings: Caches 128-dimensional TransE-style translational embeddings
-- for each knowledge node. Used by the Link Predictor Service to compute predicted
-- relationships via the score function: ||h + r - t||.

CREATE TABLE "knowledge_predicted_links" (
	"id" serial PRIMARY KEY NOT NULL,
	"organization_id" integer NOT NULL,
	"source_node_id" integer NOT NULL,
	"target_node_id" integer NOT NULL,
	"predicted_relation" text NOT NULL,
	"confidence_score" numeric(4, 3) NOT NULL,
	"status" text DEFAULT 'predicted' NOT NULL,
	"reviewed_by" text,
	"reviewed_at" timestamp,
	"created_at" timestamp DEFAULT now() NOT NULL
);
--> statement-breakpoint
CREATE TABLE "knowledge_node_embeddings" (
	"id" serial PRIMARY KEY NOT NULL,
	"node_id" integer NOT NULL,
	"organization_id" integer NOT NULL,
	"embedding" jsonb NOT NULL,
	"updated_at" timestamp DEFAULT now() NOT NULL
);
--> statement-breakpoint
